metadata.er-schema:
{
  "title": "looply · 售后模块 实体关系图",
  "version": "v1.0 · 2026-07-30",
  "tables": [
    {
      "name": "after_sale_policy",
      "comment": "售后政策",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "market_id",
          "comment": "适用市场（→ market）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "scope_type",
          "comment": "适用范围类型（全市场/品类/商品）",
          "constraint": ""
        },
        {
          "name": "scope_value",
          "comment": "适用范围值（品类或商品标识）",
          "constraint": ""
        },
        {
          "name": "priority",
          "comment": "优先级（多条命中时的覆盖顺序）",
          "constraint": ""
        },
        {
          "name": "is_returnable",
          "comment": "是否支持退货（1.2 特价/定制件例外）",
          "constraint": ""
        },
        {
          "name": "valid_days",
          "comment": "售后时效天数（签收后 N 天，1.1/d1）",
          "constraint": ""
        },
        {
          "name": "return_ship_days",
          "comment": "逾期未交寄关单天数（4.5/d4）",
          "constraint": ""
        },
        {
          "name": "service_fee_amount",
          "comment": "退货服务费金额（A14/d12）",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "return_address",
          "comment": "退货地址（完整文本，4.1 按 market 配）",
          "constraint": ""
        },
        {
          "name": "policy_status",
          "comment": "政策状态（启用/停用）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "A5 可配置策略实体；A17 按 market 独立配。scope 三级维度靠 priority 定覆盖顺序（越大越优先）。数值均为运营配置项，产品阶段不定具体值"
    },
    {
      "name": "after_sale_reason",
      "comment": "售后原因码",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "reason_code",
          "comment": "原因码",
          "constraint": "UNIQUE"
        },
        {
          "name": "display_text",
          "comment": "展示文案（英文）",
          "constraint": ""
        },
        {
          "name": "apply_as_type",
          "comment": "适用诉求类型（退货退款/仅退款）",
          "constraint": ""
        },
        {
          "name": "default_liability",
          "comment": "默认责任方（预填，可被运营改写）",
          "constraint": ""
        },
        {
          "name": "require_evidence",
          "comment": "是否必传举证",
          "constraint": ""
        },
        {
          "name": "sort_order",
          "comment": "排序",
          "constraint": ""
        },
        {
          "name": "reason_status",
          "comment": "启用状态",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "2.7 结构化原因码。default_liability 只做预填，终判以运营审核为准（3.3）。展示文案为英文，PRD 定义即最终展示文案"
    },
    {
      "name": "after_sale_order",
      "comment": "售后单（聚合根）",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "as_no",
          "comment": "售后单号（编码规则归技术侧定）",
          "constraint": "UNIQUE"
        },
        {
          "name": "order_id",
          "comment": "所属订单（→ order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "order_item_id",
          "comment": "订单商品行（→ order_item，一单一行）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "user_id",
          "comment": "申请人（→ user_account）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "market_id",
          "comment": "所属市场（V1 由 user 信息判定）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "policy_id",
          "comment": "命中的售后政策（→ after_sale_policy）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "as_type",
          "comment": "诉求类型（退货退款/仅退款，A6/A13）",
          "constraint": ""
        },
        {
          "name": "reason_code",
          "comment": "原因码（→ after_sale_reason）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "reason_note",
          "comment": "买家补充说明",
          "constraint": ""
        },
        {
          "name": "liability_party",
          "comment": "责任归属（平台/买家，A7）",
          "constraint": ""
        },
        {
          "name": "as_status",
          "comment": "售后单状态（8.1 双分支状态机）",
          "constraint": ""
        },
        {
          "name": "service_fee_quoted",
          "comment": "申请时告知的服务费金额（快照）",
          "constraint": ""
        },
        {
          "name": "is_overdue_approved",
          "comment": "是否超期人工特批（1.7）",
          "constraint": ""
        },
        {
          "name": "overdue_approve_note",
          "comment": "特批原因",
          "constraint": ""
        },
        {
          "name": "shipment_ref_id",
          "comment": "退货运单（→ shipments.shipment_id，弱引用）",
          "constraint": ""
        },
        {
          "name": "audit_result",
          "comment": "审核结论（通过/驳回，3.1）",
          "constraint": ""
        },
        {
          "name": "audit_note",
          "comment": "审核意见/驳回原因",
          "constraint": ""
        },
        {
          "name": "operator_id",
          "comment": "最近处理人",
          "constraint": ""
        },
        {
          "name": "operator_type",
          "comment": "处理人类型（运营/系统）",
          "constraint": ""
        },
        {
          "name": "applied_at",
          "comment": "申请时间",
          "constraint": ""
        },
        {
          "name": "audited_at",
          "comment": "审核时间",
          "constraint": ""
        },
        {
          "name": "closed_at",
          "comment": "关闭时间",
          "constraint": ""
        },
        {
          "name": "close_reason",
          "comment": "关闭原因（逾期未交寄等，4.5 不可恢复）",
          "constraint": ""
        },
        {
          "name": "completed_at",
          "comment": "完成时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "A1 一单一行：一个商品行一张单，一次退多件=多张单。A2 不走订单域 refund_request。1.8 互斥：同一 order_item_id 同时只允许一张非终态单。service_fee_quoted 是申请时告知买家的金额快照（A14 要求申请前告知），政策改价不影响在途单。market_id：订单域目前无 market 维度，V1 由 user 信息判定所属 market（已在订单侧记待优化：需补 market）。币种不冗余——售后是同一笔交易的逆向，币种必然继承订单，仅在 after_sale_refund 保留一个用于与支付域对账"
    },
    {
      "name": "after_sale_inspection",
      "comment": "验货记录",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "after_sale_order_id",
          "comment": "所属售后单（→ after_sale_order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "inspection_result",
          "comment": "验货结论（5.2/d5）",
          "constraint": ""
        },
        {
          "name": "inspection_note",
          "comment": "验货备注（可疑情况的唯一承载，S1）",
          "constraint": ""
        },
        {
          "name": "deduct_amount",
          "comment": "验货扣减金额（6.3）",
          "constraint": ""
        },
        {
          "name": "deduct_reason",
          "comment": "扣减原因",
          "constraint": ""
        },
        {
          "name": "operator_id",
          "comment": "录入人（运营）",
          "constraint": ""
        },
        {
          "name": "operator_type",
          "comment": "录入人类型",
          "constraint": ""
        },
        {
          "name": "inspected_at",
          "comment": "验货完成时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "A16 验货在线下仓完成、结果回传在线表格，本表承接运营录入的结论，不承接作业过程。S1 定 V1 不做真伪复核：无「真伪存疑」结论值、无挂起态，可疑情况只写 inspection_note。A3 只记客观结果，不含处置决策。deduct_amount 币种继承订单，不冗余存储"
    },
    {
      "name": "after_sale_refund",
      "comment": "退款方案与执行",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "after_sale_order_id",
          "comment": "所属售后单（→ after_sale_order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "order_id",
          "comment": "所属订单（冗余，供税费累计校验）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "base_amount",
          "comment": "退款基准（商品行实付，6.1）",
          "constraint": ""
        },
        {
          "name": "service_fee_amount",
          "comment": "退货服务费实扣金额（6.2）",
          "constraint": ""
        },
        {
          "name": "is_service_fee_waived",
          "comment": "服务费是否豁免（平台责任时豁免）",
          "constraint": ""
        },
        {
          "name": "deduct_amount",
          "comment": "验货扣减金额（6.3）",
          "constraint": ""
        },
        {
          "name": "refund_tax_amount",
          "comment": "退还税费（6.5，累计校验用）",
          "constraint": ""
        },
        {
          "name": "refund_amount",
          "comment": "最终退款金额（6.4）",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种",
          "constraint": ""
        },
        {
          "name": "refund_ref_no",
          "comment": "支付域退款单号（→ refund_order.refund_no）",
          "constraint": ""
        },
        {
          "name": "refund_status",
          "comment": "退款执行状态（6.6/6.8）",
          "constraint": ""
        },
        {
          "name": "operator_id",
          "comment": "定案人",
          "constraint": ""
        },
        {
          "name": "operator_type",
          "comment": "定案人类型",
          "constraint": ""
        },
        {
          "name": "refunded_at",
          "comment": "退款到账时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "A2 直接对接支付域退款单，只存 refund_ref_no 不冗余金额。6.5 税费随退款退还，refund_tax_amount 用于按 order_id 做已退税费累计校验（支付域只校验金额总额、不拆税）。order_id 为冗余字段，专供该累计校验"
    },
    {
      "name": "after_sale_attachment",
      "comment": "售后附件",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "after_sale_order_id",
          "comment": "所属售后单（→ after_sale_order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "inspection_id",
          "comment": "所属验货记录（验货取证时填）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "source_type",
          "comment": "来源（买家举证/验货取证）",
          "constraint": ""
        },
        {
          "name": "file_url",
          "comment": "文件地址",
          "constraint": ""
        },
        {
          "name": "file_type",
          "comment": "文件类型（图片/视频）",
          "constraint": ""
        },
        {
          "name": "uploader_id",
          "comment": "上传人",
          "constraint": ""
        },
        {
          "name": "uploader_type",
          "comment": "上传人类型（买家/运营）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "上传时间",
          "constraint": ""
        }
      ],
      "note": "2.8 买家在 C 端自助上传举证；5.4 运营从在线表格取图上传验货取证。两种来源靠 source_type 区分。举证必须跟单走且带审计，不能只留在外部表格。约束：inspection_id 非空时，其所属售后单必须与 after_sale_order_id 一致。保留 inspection_id 而非只挂售后单——验货照片的父本来就是那次验货，且未来若允许复验（inspection 变 1:N）该字段必需"
    },
    {
      "name": "order",
      "comment": "订单（订单域）",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "order_no",
          "comment": "订单号",
          "constraint": "UNIQUE"
        }
      ],
      "note": "外部拥有，售后只读 + 反写商品行退款状态"
    },
    {
      "name": "order_item",
      "comment": "订单商品行（订单域）",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "refund_status",
          "comment": "退款状态（售后域按既有语义反写）",
          "constraint": ""
        },
        {
          "name": "fulfillment_status",
          "comment": "发货状态（售后只读不改写；入口以已发货为界）",
          "constraint": ""
        },
        {
          "name": "condition_grade",
          "comment": "成色等级快照（验货比对基准）",
          "constraint": ""
        }
      ],
      "note": "9.1 售后走到退款环节才置 refund_status=退款中，到账置已退款；不在申请或审核通过时置。A12 订单表不为售后新增状态字段，「售后中」由订单侧实时查本域聚合（d13）"
    },
    {
      "name": "refund_order",
      "comment": "退款单（支付域）",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "refund_no",
          "comment": "退款单号（售后弱引用）",
          "constraint": "UNIQUE"
        }
      ],
      "note": "A2 售后单直接对接本表。只存 refund_no 引用，不冗余金额。注意：订单域的 refund_request 仅服务发货前退款，售后不使用它"
    },
    {
      "name": "shipments",
      "comment": "物流运单（物流信息服务）",
      "columns": [
        {
          "name": "shipment_id",
          "comment": "运单 UUID（对外主键，不可变）",
          "constraint": "UNIQUE"
        },
        {
          "name": "business_order_no",
          "comment": "业务单号（非唯一索引，售后传订单号）",
          "constraint": ""
        },
        {
          "name": "internal_status",
          "comment": "标准化物流状态（已送达=到仓时点唯一来源）",
          "constraint": ""
        }
      ],
      "note": "A15 售后注册退货运单后获得轨迹与主动通知。business_order_no 为非唯一索引，故 1 订单号 = N 运单，支撑 A1「多张售后单共用一个退货运单号」。售后只存 shipment_id，不冗余承运商与运单号（运单号可被 PATCH 修正、改承运商会切平台清轨迹，冗余必脏）"
    },
    {
      "name": "market",
      "comment": "销售市场（Market）",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "A17 V1 覆盖美国站 + 香港站，时效/服务费/退货地址三项按 market 独立配置"
    },
    {
      "name": "user_account",
      "comment": "用户（登录注册域）",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "外部拥有，售后只读"
    }
  ],
  "relations": [
    {
      "from": "market",
      "to": "after_sale_policy",
      "type": "1:N",
      "label": "按市场配政策",
      "color": "#7B4FC9"
    },
    {
      "from": "after_sale_policy",
      "to": "after_sale_order",
      "type": "1:N",
      "label": "命中政策",
      "color": "#7B4FC9"
    },
    {
      "from": "after_sale_reason",
      "to": "after_sale_order",
      "type": "1:N",
      "label": "原因码",
      "color": "#7B4FC9"
    },
    {
      "from": "order",
      "to": "after_sale_order",
      "type": "1:N",
      "label": "订单可多次售后",
      "color": "#6B7280"
    },
    {
      "from": "order_item",
      "to": "after_sale_order",
      "type": "1:N",
      "label": "一单一行 · 同时只允许一张非终态",
      "color": "#1565C0",
      "penwidth": 1.8
    },
    {
      "from": "user_account",
      "to": "after_sale_order",
      "type": "1:N",
      "label": "申请人",
      "color": "#6B7280"
    },
    {
      "from": "shipments",
      "to": "after_sale_order",
      "type": "1:N",
      "label": "多张单共用一个退货运单",
      "color": "#1565C0",
      "penwidth": 1.8,
      "style": "dashed"
    },
    {
      "from": "after_sale_order",
      "to": "after_sale_inspection",
      "type": "1:1",
      "label": "仅退货退款分支",
      "color": "#1565C0",
      "penwidth": 1.6
    },
    {
      "from": "after_sale_order",
      "to": "after_sale_refund",
      "type": "1:1",
      "label": "退款方案",
      "color": "#1565C0",
      "penwidth": 1.6
    },
    {
      "from": "after_sale_refund",
      "to": "refund_order",
      "type": "N:1",
      "label": "弱引用 refund_no",
      "color": "#6B7280",
      "style": "dashed"
    },
    {
      "from": "after_sale_order",
      "to": "after_sale_attachment",
      "type": "1:N",
      "label": "买家举证",
      "color": "#1565C0"
    },
    {
      "from": "after_sale_inspection",
      "to": "after_sale_attachment",
      "type": "1:N",
      "label": "验货取证",
      "color": "#1565C0"
    },
    {
      "from": "after_sale_order",
      "to": "order_item",
      "type": "N:1",
      "label": "反写退款状态",
      "color": "#C0392B",
      "style": "dashed"
    }
  ],
  "design_rules": {
    "A1_一单一行": "一个商品行一张售后单；一次退多件=多张单。多件同包裹寄回时共用一个退货运单号，注册物流追踪时业务单号传订单号（复用物流服务 1 订单号 = N 运单），不新造退货包裹实体",
    "A2_退款链路": "售后单不走订单域 refund_request，直接对接支付域 refund_order；refund_request 仅服务发货前退款",
    "A3_域边界": "售后只记客观验货结果，处置决策（能否再售/降级/报废）与执行均归商品域，本域无处置字段",
    "A12_订单侧状态": "订单表不为售后新增状态字段；订单详情页显示「售后中」由订单侧按 order_item_id 实时查本域聚合。售后单表的 order_id / order_item_id 必须建索引，这是该方案成立的前提",
    "A14_退货服务费": "正逆向均不向买家收运费；退款时统一扣一笔按 market 配置的服务费；平台责任豁免、买家责任才扣；验货结论一致时同样扣除。系统内不存在「退货运费」独立概念",
    "A15_物流接入": "接入物流信息服务，只存 shipment_id；轨迹与承运商信息不冗余；「已送达」是到仓时点唯一来源",
    "A16_验货作业": "验货在线下仓完成并回传在线表格，运营核对后录入。V1 不对接在线表格，但验货录入表单需按其字段设计，以便后续对接不重构",
    "S1_真伪复核": "V1 不做：无「真伪存疑」结论值、无挂起态。可疑情况只写 inspection_note",
    "S3_税费累计校验": "税费随退款退还；必须按 order_id 做已退税费累计校验（支付域只校验金额总额、不拆税）。并发场景需按 order_id 加锁",
    "组9_V1不做": "库存回流与商品重新上架 V1 均不做（退货只放仓内），本域不建库存事件与处置指令相关实体",
    "命名规范": "随订单域：表名单数 snake_case、主键 id、业务单号 <x>_no[UK]、外键 <被引实体>_id、跨域弱引用 _ref_no/_ref_id 不建 FK、多状态带前缀、时间戳 _at、含金额表必带 currency_code、操作人 operator_id + operator_type 成对",
    "A7_责任二分类_与G1文档的已知差异": "本 ER 按【平台责任 / 买家责任】二分类建模。G1 概览文档 A7/3.3/S2/4.6 仍写三分类（含物流责任），系 2026-07-30 用户口头指导后的已知差异，不视为冲突——物流出问题属平台与物流商之间的事，对买家而言即平台责任，平台先赔付再线下索赔；物流原因由 after_sale_reason 承载（原因码记「为什么」，liability_party 记「谁承担」）。推论：仅退款场景天然归平台责任，自动豁免服务费",
    "售后单状态机骨架": "8.1 两条分支（具体枚举命名归后续环节）：① 退货退款：待审核 → 待寄回(已告知运单号) → 退货在途 → 待验货 → 待退款 → 已完成；旁支 已驳回 / 已关闭(逾期未交寄，不可恢复) / 已拒退(验货不符或空包)。② 仅退款：待审核 → 待退款 → 已完成；旁支 已驳回 / 已关闭。「待验货」由 shipments.internal_status=已送达 自动推进（A15/5.1），无人工签收登记",
    "本期结构取舍": "① 时间线(8.3)与操作日志(8.4)合表 after_sale_log，靠 is_customer_visible 区分——同一动作既要对买家展示又要留痕，分表会双写。② 协商改方案(3.4)不做退款方案版本化，调整过程由 after_sale_log 的 before/after 承载；若后续需要方案多版本，after_sale_refund 改 1:N 即可，结构不用动。③ 退货地址存完整文本快照而非引用地址库——它是仓库地址、要直接发给买家看，且需随 market 配",
    "本图范围_不画不等于不建": "本图只呈现售后域【核心实体关系】，用于确认设计大方向。日志/时间线(8.3、8.4)、邮件通知记录(8.5)等留痕与触达类实体本期不在图内体现，但它们都是 ✅V1 能力、建表时必须补：① 时间线与操作日志（涉及资金必须留痕：审核结论、责任判定、服务费调整、验货扣减、超期特批、关单）；② 售后节点邮件记录（消息通知模块仅提供通道，节点与内容由本域定义，需覆盖两个 market 的语言）",
    "待技术侧定": "售后单号编码规则归技术环节确定，产品阶段不定"
  }
}
